  /// Returns a new [Provider] instance and imports its values from
  /// [value] if it's a [Map], null otherwise.
  // ignore: prefer_constructors_over_static_methods
  static Provider? fromJson(dynamic value) {
    if (value is Map) {
      final json = value.cast<String, dynamic>();

      // Ensure that the map contains the required keys.
      // Note 1: the values aren't checked for validity beyond being non-null.
      // Note 2: this code is stripped in release mode!
      assert(() {
        requiredKeys.forEach((key) {
          assert(json.containsKey(key), 'Required key "Provider[$key]" is missing from JSON.');
          assert(json[key] != null, 'Required key "Provider[$key]" has a null value in JSON.');
        });
        return true;
      }());

      return Provider(
        apiVersion: mapValueOfType<String>(json, r'apiVersion'),
        asset: mapValueOfType<String>(json, r'asset'),
        browserUrl: mapValueOfType<String>(json, r'browserUrl'),
        category: mapValueOfType<String>(json, r'category'),
        chain: mapValueOfType<String>(json, r'chain'),
        clientId: mapValueOfType<String>(json, r'clientId'),
        clientSecret: mapValueOfType<String>(json, r'clientSecret'),
        compatibleProvider: mapValueOfType<String>(json, r'compatibleProvider'),
        configText: mapValueOfType<String>(json, r'configText'),
        contractMethod: mapValueOfType<String>(json, r'contractMethod'),
        contractName: mapValueOfType<String>(json, r'contractName'),
        createdTime: mapValueOfType<String>(json, r'createdTime'),
        currency: mapValueOfType<String>(json, r'currency'),
        displayName: mapValueOfType<String>(json, r'displayName'),
        enableThinking: mapValueOfType<bool>(json, r'enableThinking'),
        errorText: mapValueOfType<String>(json, r'errorText'),
        flavor: mapValueOfType<String>(json, r'flavor'),
        frequencyPenalty: num.parse('${json[r'frequencyPenalty']}'),
        inputPricePerThousandTokens: num.parse('${json[r'inputPricePerThousandTokens']}'),
        isDefault: mapValueOfType<bool>(json, r'isDefault'),
        isRemote: mapValueOfType<bool>(json, r'isRemote'),
        mcpTools: AgentMcpTools.listFromJson(json[r'mcpTools']),
        name: mapValueOfType<String>(json, r'name'),
        network: mapValueOfType<String>(json, r'network'),
        outputPricePerThousandTokens: num.parse('${json[r'outputPricePerThousandTokens']}'),
        owner: mapValueOfType<String>(json, r'owner'),
        presencePenalty: num.parse('${json[r'presencePenalty']}'),
        providerKey: mapValueOfType<String>(json, r'providerKey'),
        providerUrl: mapValueOfType<String>(json, r'providerUrl'),
        rawText: mapValueOfType<String>(json, r'rawText'),
        region: mapValueOfType<String>(json, r'region'),
        resultSummary: mapValueOfType<String>(json, r'resultSummary'),
        runner: mapValueOfType<String>(json, r'runner'),
        signCert: mapValueOfType<String>(json, r'signCert'),
        signKey: mapValueOfType<String>(json, r'signKey'),
        state: mapValueOfType<String>(json, r'state'),
        subType: mapValueOfType<String>(json, r'subType'),
        target: mapValueOfType<String>(json, r'target'),
        targetMode: mapValueOfType<String>(json, r'targetMode'),
        temperature: num.parse('${json[r'temperature']}'),
        testContent: mapValueOfType<String>(json, r'testContent'),
        text: mapValueOfType<String>(json, r'text'),
        topK: mapValueOfType<int>(json, r'topK'),
        topP: num.parse('${json[r'topP']}'),
        type: mapValueOfType<String>(json, r'type'),
        userCert: mapValueOfType<String>(json, r'userCert'),
        userKey: mapValueOfType<String>(json, r'userKey'),
      );
    }
    return null;
  }

  static List<Provider> listFromJson(dynamic json, {bool growable = false,}) {
    final result = <Provider>[];
    if (json is List && json.isNotEmpty) {
      for (final row in json) {
        final value = Provider.fromJson(row);
        if (value != null) {
          result.add(value);
        }
      }
    }
    return result.toList(growable: growable);
  }

  static Map<String, Provider> mapFromJson(dynamic json) {
    final map = <String, Provider>{};
    if (json is Map && json.isNotEmpty) {
      json = json.cast<String, dynamic>(); // ignore: parameter_assignments
      for (final entry in json.entries) {
        final value = Provider.fromJson(entry.value);
        if (value != null) {
          map[entry.key] = value;
        }
      }
    }
    return map;
  }

  // maps a json object with a list of Provider-objects as value to a dart map
  static Map<String, List<Provider>> mapListFromJson(dynamic json, {bool growable = false,}) {
    final map = <String, List<Provider>>{};
    if (json is Map && json.isNotEmpty) {
      // ignore: parameter_assignments
      json = json.cast<String, dynamic>();
      for (final entry in json.entries) {
        map[entry.key] = Provider.listFromJson(entry.value, growable: growable,);
      }
    }
    return map;
  }

